/*
 * headless_opattributes_verbs.c - Opattributes processor verb stubs
 *
 * Originally generated by tools/kernelverbs_parser/generate_processor_stubs.py,
 * now contains stub implementations for opattributes verbs.
 *
 * DO NOT regenerate - this file contains stub implementations.
 *
 * NOTE (2026-01-12): opattributes is a GUI-centric feature for managing
 * binary attributes stored in outline node refcon. In headless CLI mode,
 * these operations are not supported since:
 * 1. No outline target available (op.attributes works on current node in GUI)
 * 2. Attribute serialization is complex and GUI-specific
 * 3. No real use cases for CLI operations
 *
 * This follows the pattern of other GUI-only verbs (op.hoist, op.dehoist).
 *
 * Future: For GUI builds, implement full pack/unpack with BE64 compliance.
 *
 * @STUB - Returns "not supported in headless mode" errors
 */

#include "frontier.h"
#include "standard.h"

#include "memory.h"
#include "strings.h"
#include "lang.h"
#include "langinternal.h"
#include "tablestructure.h"
#include "op.h"
#include "opinternal.h"

/* Token enum for all verbs in the opattributes processor */
/* Exposed publicly for testing */
enum {
    opav_addgroup = 0,
    opav_getall = 1,
    opav_getone = 2,
    opav_makeempty = 3,
    opav_setone = 4
};

/* Public interface for testing */
extern boolean opattributes_valueproc(short token, hdltreenode hparam1,
                                     tyvaluerecord *vreturned,
                                     bigstring bserror);

static void seterrorstring(const char *msg, bigstring bserror) {
    if (bserror == NULL)
        return;
    copyctopstring(msg, bserror);
}

boolean opattributes_valueproc(short token, hdltreenode hparam1,
                               tyvaluerecord *vreturned,
                               bigstring bserror) {
    /*
     * Headless stub for opattributes verbs
     *
     * opattributes operations are GUI-centric and have no meaningful
     * use in headless CLI environment. All verbs return error.
     */
    (void) token;          /* Suppress unused parameter warning */
    (void) hparam1;        /* Suppress unused parameter warning */
    (void) vreturned;      /* Suppress unused parameter warning */

    seterrorstring("op.attributes verbs are not supported in headless mode", bserror);
    return false;
}

boolean opattributesinitverbs(void) {
    /*
     * Initialize the opattributes processor and register all verbs.
     *
     * This creates a top-level function processor "opattributes" and registers
     * all 5 opattributes verbs with their token values. The verbs are:
     *
     * - opattributes.addgroup(groupName)
     * - opattributes.getall()
     * - opattributes.getone(groupName, itemName)
     * - opattributes.makeempty()
     * - opattributes.setone(groupName, itemName, value)
     *
     * In headless mode, all these verbs return "not supported" errors since
     * opattributes is GUI-centric and requires an active outline target.
     *
     * Returns: true if initialization succeeds, false on error.
     */
    hdlhashtable htable = nil;
    bigstring bsname;

    copystring(BIGSTRING("\popattributes"), bsname);

    if (!newfunctionprocessor(bsname, &opattributes_valueproc, false, &htable))
        return false;

    pushhashtable(htable);

    #define ADD_VERB(name, tok) do { \
        bigstring bs; \
        copystring(name, bs); \
        if (!langaddkeyword(bs, tok)) { \
            pophashtable(); \
            return false; \
        } \
    } while(0)

    ADD_VERB(BIGSTRING("\paddgroup"), opav_addgroup);
    ADD_VERB(BIGSTRING("\pgetall"), opav_getall);
    ADD_VERB(BIGSTRING("\pgetone"), opav_getone);
    ADD_VERB(BIGSTRING("\pmakeempty"), opav_makeempty);
    ADD_VERB(BIGSTRING("\psetone"), opav_setone);

    #undef ADD_VERB

    pophashtable();
    return true;
}
